const issueEndpoint='https://api.github.com/repos/marzlo/Economist/contents/issues.json';
let issueSha=null,syncBusy=false,syncQueue=Promise.resolve(),syncConflict=false;
if(!localStorage.getItem('economist-legacy-backup'))localStorage.setItem('economist-legacy-backup',JSON.stringify(issues));
let localImport=JSON.parse(localStorage.getItem('economist-legacy-backup'));
const syncMessage=text=>{const el=$('#sync-message');el.textContent=text;el.classList.toggle('sync-error',/失敗|衝突|無效|錯誤/.test(text));};
const token=()=>localStorage.getItem('economist-github-token')||'';
const headers=()=>({Accept:'application/vnd.github+json',...(token()?{Authorization:'Bearer '+token()}:{})});
const encodeIssues=value=>btoa(Array.from(new TextEncoder().encode(JSON.stringify(value,null,2)+'\n'),b=>String.fromCharCode(b)).join(''));
const decodeIssues=value=>JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(value.replace(/\s/g,'')),c=>c.charCodeAt(0))));
function normalizeIssues(value){if(!Array.isArray(value)||!value.every(i=>typeof i.id==='string'&&typeof i.name==='string'&&Array.isArray(i.keys)))throw Error('議題資料格式不正確');return value.map(i=>({...i,entries:i.entries||[],status:i.status||'觀察中',then:i.then||'',note:i.note||''}))}
async function remoteIssues(){const r=await fetch(issueEndpoint+'?ref=main&t='+Date.now(),{headers:headers(),cache:'no-store',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error(r.status===401?'權杖無效或已過期':'GitHub 讀取失敗（'+r.status+'）');const data=await r.json();return {sha:data.sha,issues:normalizeIssues(decodeIssues(data.content))}}
async function pullIssues(){if(syncBusy){syncMessage('正在儲存，請稍後再同步');return}if(localStorage.getItem('economist-sync-pending')){syncMessage('本機有未同步內容，請先設定權杖並按「匯入本機筆記」；匯入前請先匯出備份。');return}try{syncMessage('正在讀取 GitHub 議題…');const remote=await remoteIssues();issueSha=remote.sha;issues=remote.issues;syncConflict=false;selected=selected?issues.find(i=>i.id===selected.id)||null:null;localStorage.setItem('reading-issues',JSON.stringify(issues));renderIssues();renderNews();syncMessage('已同步 GitHub · '+new Date().toLocaleTimeString('zh-TW'))}catch(e){syncMessage(e.message+'；保留本機資料')}}
window.saveGitHubIssues=function(){localStorage.setItem('economist-sync-pending','1');const snapshot=JSON.parse(JSON.stringify(issues));syncQueue=syncQueue.then(async()=>{if(!token()){syncMessage('已保存在本機；請設定 GitHub 權杖後匯入本機筆記。');return}if(syncConflict){syncMessage('有同步衝突；請匯出備份，再匯入本機筆記合併。');return}syncBusy=true;try{syncMessage('正在儲存至 GitHub…');if(!issueSha)throw Error('請先匯入本機筆記，完成首次同步');const r=await fetch(issueEndpoint,{method:'PUT',signal:AbortSignal.timeout(20000),headers:{...headers(),'Content-Type':'application/json'},body:JSON.stringify({message:'Update reading issues and notes',content:encodeIssues(snapshot),sha:issueSha,branch:'main'})});if(r.status===409||r.status===422){syncConflict=true;throw Error('其他裝置已更新，未覆蓋 GitHub；請匯出備份後匯入合併')}if(!r.ok)throw Error('儲存失敗（'+r.status+'），請檢查權杖的 Contents 寫入權限');issueSha=(await r.json()).content.sha;if(JSON.stringify(snapshot)===JSON.stringify(issues))localStorage.removeItem('economist-sync-pending');syncMessage('✓ 已儲存至 GitHub：'+snapshot.length+' 個議題、'+snapshot.reduce((n,i)=>n+(i.entries?.length||0),0)+' 筆記事。其他裝置按「同步議題」即可取得')}catch(e){syncMessage(e.message+'；本機內容已保留')}finally{syncBusy=false}})};
$('#sync-settings').onclick=()=>{$('#sync-token').value='';$('#sync-dialog').showModal()};
$('#sync-close').onclick=()=>$('#sync-dialog').close();
$('#sync-forget').onclick=()=>{localStorage.removeItem('economist-github-token');$('#sync-dialog').close();syncMessage('已清除此裝置權杖')};
$('#sync-form').onsubmit=e=>{e.preventDefault();const value=$('#sync-token').value.trim();if(!value)return;localStorage.setItem('economist-github-token',value);$('#sync-token').value='';$('#sync-dialog').close();syncMessage('權杖已設定。原有筆記請按「匯入本機筆記」，新編輯將自動儲存至 GitHub。')};
$('#sync-pull').onclick=pullIssues;
$('#sync-import').onclick=async()=>{if(syncBusy){syncMessage('正在儲存，請稍後再匯入');return}if(!token()){syncMessage('尚未設定 GitHub 權杖，請在設定視窗貼上');$('#sync-dialog').showModal();return}if(!confirm('將本機議題合併到 GitHub。同名 ID 的判斷以本機為準，同 ID 記事以本機版本為準；請先匯出備份。確定匯入？'))return;const button=$('#sync-import');button.disabled=true;button.textContent='匯入中…';syncMessage('正在讀取 GitHub 並合併本機筆記…');try{const local=localStorage.getItem('economist-sync-pending')?issues:localImport;const remote=await remoteIssues();const map=new Map(remote.issues.map(i=>[i.id,i]));for(const i of normalizeIssues(local)){const old=map.get(i.id);const entries=new Map((old?.entries||[]).map(e=>[e.id,e]));i.entries.forEach(e=>entries.set(e.id,e));map.set(i.id,{...old,...i,entries:[...entries.values()]})}issues=[...map.values()];issueSha=remote.sha;syncConflict=false;localImport=JSON.parse(JSON.stringify(issues));save();renderIssues();renderNews();await syncQueue;$('#sync-message').scrollIntoView({behavior:'smooth',block:'center'})}catch(e){syncMessage('匯入失敗：'+e.message)}finally{button.disabled=false;button.textContent='匯入本機筆記'}};
setTimeout(pullIssues,0);
